        self.lines = await convert_yielded(self.read_lines())
    async def write(self):
        return await convert_yielded(self.write_lines())
    def read_lines(self):
        lines = [""]
        try:
            lines = self.path.read_text(encoding="utf-8").splitlines()
        except FileNotFoundError:
            pass
