    crash_handler_class = Type(crashhandler.CrashHandler)
    def __init__(self, **kwargs):
        super(BaseIPythonApplication, self).__init__(**kwargs)
        try:
            os.getcwd()
        except:
            self.log.error("Current working directory doesn't exist.")
