            "Exception raised in 'camera_record' when setting user grp: "
            "{err}".format(err=e))
def camera_timelapse_video(form_camera):
    messages = {
        "success": [],
        "info": [],
        "warning": [],
        "error": []
    }
    if not os.path.exists("/usr/bin/ffmpeg"):
