                    l_ann.setParent(obj._obj)
                    l_ann.setChild(ann._obj)
                    new_links.append(l_ann)
        if len(new_links) > 0:
            try:
                self.conn.saveArray(new_links)
            except omero.ValidationException:
                for link in new_links:
                    try:
                        self.conn.saveObject(link)
                    except Exception:
                        pass
        return ann.getId()
