        A potentially expensive operation that removes all data
        already retrieved from the buffer.
        """
        buf = self.buf
        if buf is None:
            self.strbuf = b""
            return
        buf.prune()
        if self.overflowed:
            sz = buf.__len__()
            if sz < self.overflow:
                self._set_small_buffer()
