        source_pos: Optional[Tuple[int, int]] = None,
        annotation: Optional[str] = None,
        error_msg: Optional[str] = None,
        mutable: bool = True,
        add_gas_estimate: int = 0,
        encoding: Encoding = Encoding.VYPER,
    ):
        if args is None:
            args = []
