    login_url = urljoin(flask.request.url_root, flask.url_for('app.login'))
    for location in flask.request.values.get("next"), flask.request.referrer:
        if not location:
            continue
        if location in (flask.request.url, login_url):
            continue
        if is_safe_url(location):
            return location
    return fallback
