    if not session.get("authenticated", False):
        return perms
    perms["ANY"] = True
    if session.get("role") == Role.ADMIN:
        for key in perms.keys():
            perms[key] = True
    elif session.get("perms"):
        p = session.get("perms")
        perms.update(get_permission(p))
    return perms
