def is_maintainer():
    if cherrypy.serving.request.handler is None:
        return True
    if not cherrypy.serving.request.currentuser or not cherrypy.serving.request.currentuser.is_maintainer:
        raise cherrypy.HTTPError("403 Forbidden")
