class File(
    PathReprProvider,
    Persistent,
    Implicit,
    PropertyManager,
    RoleManager,
    Item_w__name__,
    Cacheable
):
    meta_type = 'File'
    zmi_icon = 'far fa-file-archive'
    security = ClassSecurityInfo()
    precondition = ''
    size = None
    manage_editForm = DTMLFile('dtml/fileEdit', globals(),
                               Kind='File', kind='file')
    manage = manage_main = manage_editForm
    manage_uploadForm = manage_editForm
    manage_options = (({'label': 'Edit', 'action': 'manage_main'},
                       {'label': 'View', 'action': ''})
                      + PropertyManager.manage_options
                      + RoleManager.manage_options
                      + Item_w__name__.manage_options
                      + Cacheable.manage_options)
    _properties = (
        {'id': 'title', 'type': 'string'},
        {'id': 'content_type', 'type': 'string'},
    )
    def __init__(self, id, title, file, content_type='', precondition=''):
        self.__name__ = id
        self.title = title
        self.precondition = precondition
        data, size = self._read_data(file)
        content_type = self._get_content_type(file, data, id, content_type)
        self.update_data(data, content_type, size)
    def _if_modified_since_request_handler(self, REQUEST, RESPONSE):
        header = REQUEST.get_header('If-Modified-Since', None)
        if header is not None:
            header = header.split(';')[0]
            try:
                mod_since = int(DateTime(header).timeTime())
            except Exception:
                mod_since = None
            if mod_since is not None:
                if self._p_mtime:
                    last_mod = int(self._p_mtime)
                else:
                    last_mod = 0
                if last_mod > 0 and last_mod <= mod_since:
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setStatus(304)
                    return True
    def _range_request_handler(self, REQUEST, RESPONSE):
        range = REQUEST.get_header('Range', None)
        request_range = REQUEST.get_header('Request-Range', None)
        if request_range is not None:
            range = request_range
        if_range = REQUEST.get_header('If-Range', None)
        if range is not None:
            ranges = HTTPRangeSupport.parseRange(range)
            if if_range is not None:
                if len(if_range) > 1 and if_range[:2] == 'ts':
                    if if_range != self.http__etag():
                        ranges = None
                else:
                    date = if_range.split(';')[0]
                    try:
                        mod_since = int(DateTime(date).timeTime())
                    except Exception:
                        mod_since = None
                    if mod_since is not None:
                        if self._p_mtime:
                            last_mod = int(self._p_mtime)
                        else:
                            last_mod = 0
                        if last_mod > mod_since:
                            ranges = None
            if ranges:
                satisfiable = 0
                for start, end in ranges:
                    if start < self.size:
                        satisfiable = 1
                        break
                if not satisfiable:
                    RESPONSE.setHeader(
                        'Content-Range', 'bytes */%d' % self.size
                    )
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Content-Length', self.size)
                    RESPONSE.setStatus(416)
                    return True
                ranges = HTTPRangeSupport.expandRanges(ranges, self.size)
                if len(ranges) == 1:
                    start, end = ranges[0]
                    size = end - start
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Content-Length', size)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setHeader(
                        'Content-Range',
                        'bytes %d-%d/%d' % (start, end - 1, self.size)
                    )
                    RESPONSE.setStatus(206)
                    data = self.data
                    if isinstance(data, bytes):
                        RESPONSE.write(data[start:end])
                        return True
                    pos = 0
                    while data is not None:
                        length = len(data.data)
                        pos = pos + length
                        if pos > start:
                            lstart = length - (pos - start)
                            if lstart < 0:
                                lstart = 0
                            if end <= pos:
                                lend = length - (pos - end)
                                RESPONSE.write(data[lstart:lend])
                                break
                            RESPONSE.write(data[lstart:])
                        data = data.next
                    return True
                else:
                    boundary = _make_boundary()
                    size = (8 + len(boundary)
                            + len(ranges) * (
                                49 + len(boundary)
                                + len(self.content_type)
                                + len('%d' % self.size)))
                    for start, end in ranges:
                        size = (size + len('%d%d' % (start, end - 1))
                                + end - start)
                    draftprefix = (request_range is not None) and 'x-' or ''
                    RESPONSE.setHeader('Content-Length', size)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader(
                        'Content-Type',
                        f'multipart/{draftprefix}byteranges;'
                        f' boundary={boundary}'
                    )
                    RESPONSE.setStatus(206)
                    data = self.data
                    pdata_map = {}
                    pdata_map[0] = data
                    for start, end in ranges:
                        RESPONSE.write(
                            b'\r\n--'
                            + boundary.encode('ascii')
                            + b'\r\n'
                        )
                        RESPONSE.write(
                            b'Content-Type: '
                            + self.content_type.encode('ascii')
                            + b'\r\n'
                        )
                        RESPONSE.write(
                            b'Content-Range: bytes '
                            + str(start).encode('ascii')
                            + b'-'
                            + str(end - 1).encode('ascii')
                            + b'/'
                            + str(self.size).encode('ascii')
                            + b'\r\n\r\n'
                        )
                        if isinstance(data, bytes):
                            RESPONSE.write(data[start:end])
                        else:
                            first_size = len(pdata_map[0].data)
                            if start < first_size:
                                closest_pos = 0
                            else:
                                closest_pos = (
                                    ((start - first_size) >> 16 << 16)
                                    + first_size
                                )
                            pos = min(closest_pos, max(pdata_map.keys()))
                            data = pdata_map[pos]
                            while data is not None:
                                length = len(data.data)
                                pos = pos + length
                                if pos > start:
                                    lstart = length - (pos - start)
                                    if lstart < 0:
                                        lstart = 0
                                    if end <= pos:
                                        lend = length - (pos - end)
                                        RESPONSE.write(data[lstart:lend])
                                        break
                                    RESPONSE.write(data[lstart:])
                                data = data.next
                                pdata_map[pos] = data
                    del pdata_map
                    RESPONSE.write(
                        b'\r\n--' + boundary.encode('ascii') + b'--\r\n')
                    return True
    def index_html(self, REQUEST, RESPONSE):
        """
        The default view of the contents of a File or Image.
        Returns the contents of the file or image.  Also, sets the
        Content-Type HTTP header to the objects content type.
        """
        if self._if_modified_since_request_handler(REQUEST, RESPONSE):
            self.ZCacheable_set(None)
            return b''
        if self.precondition and hasattr(self, str(self.precondition)):
            c = getattr(self, str(self.precondition))
            if hasattr(c, 'isDocTemp') and c.isDocTemp:
                c(REQUEST['PARENTS'][1], REQUEST)
            else:
                c()
        if self._range_request_handler(REQUEST, RESPONSE):
            return b''
        RESPONSE.setHeader('Last-Modified', rfc1123_date(self._p_mtime))
        RESPONSE.setHeader('Content-Type', self.content_type)
        RESPONSE.setHeader('Content-Length', self.size)
        RESPONSE.setHeader('Accept-Ranges', 'bytes')
        if self.ZCacheable_isCachingEnabled():
            result = self.ZCacheable_get(default=None)
            if result is not None:
                return result
        self.ZCacheable_set(None)
        data = self.data
        if isinstance(data, bytes):
            RESPONSE.setBase(None)
            return data
        while data is not None:
            RESPONSE.write(data.data)
            data = data.next
        return b''
    def view_image_or_file(self, URL1):
        """The default view of the contents of the File or Image."""
        raise Redirect(URL1)
    def PrincipiaSearchSource(self):
        """Allow file objects to be searched."""
        if self.content_type.startswith('text/'):
            return bytes(self.data)
        return b''
    def update_data(self, data, content_type=None, size=None):
        if isinstance(data, str):
            raise TypeError('Data can only be bytes or file-like. '
                            'Unicode objects are expressly forbidden.')
        if content_type is not None:
            self.content_type = content_type
        if size is None:
            size = len(data)
        self.size = size
        self.data = data
        self.ZCacheable_invalidate()
        self.ZCacheable_set(None)
        self.http__refreshEtag()
    def _get_encoding(self):
        """Get the canonical encoding for ZMI."""
        return ZPublisher.HTTPRequest.default_encoding
    def manage_edit(
        self,
        title,
        content_type,
        precondition='',
        filedata=None,
        REQUEST=None
    ):
        """
        Changes the title and content type attributes of the File or Image.
        """
        if self.wl_isLocked():
            raise ResourceLockedError("File is locked.")
        self.title = str(title)
        self.content_type = str(content_type)
        if precondition:
            self.precondition = str(precondition)
        elif self.precondition:
            del self.precondition
        if filedata is not None:
            if isinstance(filedata, str):
                filedata = filedata.encode(self._get_encoding())
            self.update_data(filedata, content_type, len(filedata))
        else:
            self.ZCacheable_invalidate()
        notify(ObjectModifiedEvent(self))
        if REQUEST:
            message = "Saved changes."
            return self.manage_main(
                self, REQUEST, manage_tabs_message=message)
    def manage_upload(self, file='', REQUEST=None):
        """
        Replaces the current contents of the File or Image object with file.
        The file or images contents are replaced with the contents of 'file'.
        """
        if self.wl_isLocked():
            raise ResourceLockedError("File is locked.")
        if file:
            data, size = self._read_data(file)
            content_type = self._get_content_type(file, data, self.__name__,
                                                  'application/octet-stream')
            self.update_data(data, content_type, size)
            notify(ObjectModifiedEvent(self))
            msg = 'Saved changes.'
        else:
            msg = 'Please select a file to upload.'
        if REQUEST:
            return self.manage_main(
                self, REQUEST, manage_tabs_message=msg)
    def _get_content_type(self, file, body, id, content_type=None):
        headers = getattr(file, 'headers', None)
        if headers and 'content-type' in headers:
            content_type = headers['content-type']
        else:
            if not isinstance(body, bytes):
                body = body.data
            content_type, enc = guess_content_type(
                getattr(file, 'filename', id), body, content_type)
        return content_type
    def _read_data(self, file):
        import transaction
        n = 1 << 16
        if isinstance(file, str):
            raise ValueError("Must be bytes")
        if isinstance(file, bytes):
            size = len(file)
            if size < n:
                return (file, size)
            file = BytesIO(file)
        if isinstance(file, FileUpload) and not file:
            raise ValueError('File not specified')
        if hasattr(file, '__class__') and file.__class__ is Pdata:
            size = len(file)
            return (file, size)
        seek = file.seek
        read = file.read
        seek(0, 2)
        size = end = file.tell()
        if size <= 2 * n:
            seek(0)
            if size < n:
                return read(size), size
            return Pdata(read(size)), size
        transaction.savepoint(optimistic=True)
        if self._p_jar is None:
            seek(0)
            return Pdata(read(size)), size
        _next = None
        while end > 0:
            pos = end - n
            if pos < n:
                pos = 0
            seek(pos)
            data = Pdata(read(end - pos))
            self._p_jar.add(data)
            data.next = _next
            transaction.savepoint(optimistic=True)
            data._p_deactivate()
            assert data._p_oid is not None
            assert data._p_state == -1
            _next = data
            end = pos
        return (_next, size)
    def PUT(self, REQUEST, RESPONSE):
        """Handle HTTP PUT requests"""
        self.dav__init(REQUEST, RESPONSE)
        self.dav__simpleifhandler(REQUEST, RESPONSE, refresh=1)
        type = REQUEST.get_header('content-type', None)
        file = REQUEST['BODYFILE']
        data, size = self._read_data(file)
        if isinstance(data, str):
            data = data.encode('UTF-8')
        content_type = self._get_content_type(file, data, self.__name__,
                                              type or self.content_type)
        self.update_data(data, content_type, size)
        RESPONSE.setStatus(204)
        return RESPONSE
