    yield _('CherryPy Version'), getattr(cherrypy, '__version__')
    import sqlalchemy
    yield _('SQLAlchemy Version'), getattr(sqlalchemy, '__version__')
    try:
        import ldap
        yield _('LDAP Version'), getattr(ldap, '__version__')
