        Bcfg2.Server.Admin.MetadataCore.__call__(self, args)
        try:
            opts, args = getopt.getopt(args, 'Hbko:',
                                       ['includehosts', 'includebundles',
                                        'includekey', 'outfile='])
        except getopt.GetoptError, msg:
            print msg
        hset = False
        bset = False
        kset = False
