        params.update({
            "recent": True,
            "length": templates_per_page,
            "offset": current_page
        })
        templates_info = query_internal_api("/internal/templates", "get", params=params)
    except Exception as err:
        flash(str(err), "danger")
        return redirect(url_for("create_page"))
